/* Vexorion command center — dependency-free, browser-local frontend. */
(() => {
  'use strict';
  const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',shield:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6l-8-3z M8.5 12l2.5 2.5 4.5-5',alert:'m12 3 10 17H2L12 3z M12 9v4 M12 16v.2',layers:'m12 3 10 5-10 5L2 8l10-5z M2 12l10 5 10-5 M2 16l10 5 10-5',box:'m12 2 10 5v10l-10 5-10-5V7l10-5z M2 7l10 5 10-5 M12 12v10 M7 4.5l10 5',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3 M16 3a4 4 0 0 1 0 8 M22 21v-3a4 4 0 0 0-3-3.9 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',file:'M14 2H5v20h14V7l-5-5z M14 2v6h5 M8 12h8 M8 16h6',chart:'M4 3v17h17 M8 15l4-5 4 3 5-7',settings:'m9 3-1 3-3 1v3l-2 2 2 2v3l3 1 1 3h6l1-3 3-1v-3l2-2-2-2V7l-3-1-1-3H9z M15.5 12a3.5 3.5 0 1 1-7 0 3.5 3.5 0 0 1 7 0',search:'m20 20-5-5 M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',arrow:'M5 12h14 M13 6l6 6-6 6',down:'m6 9 6 6 6-6',up:'m5 15 7-7 7 7 M12 8v12',right:'m9 5 7 7-7 7',left:'m15 5-7 7 7 7',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',play:'m9 5 11 7-11 7V5z',check:'m5 12 4 4L19 6',checkCircle:'M21 11v1a9 9 0 1 1-5.3-8.2 M8 11l4 4L22 5',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 7v5l3 2',cloud:'M7 18a5 5 0 1 1 .7-9.95A7 7 0 0 1 21 11a3.5 3.5 0 0 1-1 7H7z',network:'M9 2h6v6H9z M2 16h6v6H2z M16 16h6v6h-6z M12 8v4 M5 16v-4h14v4',database:'M20 6c0 2-3.6 4-8 4S4 8 4 6s3.6-4 8-4 8 2 8 4z M4 6v12c0 2 3.6 4 8 4s8-2 8-4V6 M4 12c0 2 3.6 4 8 4s8-2 8-4',wallet:'M3 5h16v4H3a2 2 0 0 1 0-4 M3 5v15h18V9H3 M21 13h-5v4h5',refresh:'M20 7V3l-4 4 M4 17v4l4-4 M20 7a9 9 0 0 0-15-2 M4 17a9 9 0 0 0 15 2',lock:'M5 10h14v11H5z M8 10V6a4 4 0 0 1 8 0v4 M12 15v2',key:'m15 7 2-2 5 5-2 2-2-2-5 5 M13 16a6 6 0 1 1-8.5-8.5A6 6 0 0 1 13 16z',server:'M3 3h18v7H3z M3 14h18v7H3z M7 6.5h.1 M7 17.5h.1 M11 6.5h6 M11 17.5h6',code:'m8 5-7 7 7 7 M16 5l7 7-7 7 M14 3l-4 18',activity:'M2 12h5l3-9 4 18 3-9h5',spark:'m12 2 2.7 6.9L22 12l-7.3 3.1L12 22l-2.7-6.9L2 12l7.3-3.1L12 2z',trophy:'M8 3h8v7a4 4 0 0 1-8 0V3z M8 5H4v3a4 4 0 0 0 4 4 M16 5h4v3a4 4 0 0 1-4 4 M12 14v5 M8 21h8 M9 19h6',target:'M21 12a9 9 0 1 1-9-9 M17 12a5 5 0 1 1-5-5 M12 12l9-9 M16 3h5v5',home:'m3 10 9-8 9 8v11h-7v-7h-4v7H3V10z',x:'m6 6 12 12 M6 18 18 6',filter:'M3 4h18l-7 8v7l-4 2v-9L3 4z',menu:'M3 6h18 M3 12h18 M3 18h18',info:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 11v6 M12 7v.1',external:'M14 3h7v7 M10 14 21 3 M10 3H3v18h18v-7',plus:'M12 5v14 M5 12h14',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M3 12h18 M12 3c6 5 6 13 0 18-6-5-6-13 0-18',calendar:'M4 5h16v16H4z M8 2v6 M16 2v6 M4 10h16',help:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M9.5 9a2.5 2.5 0 0 1 5 0c0 2-2.5 2-2.5 4 M12 16v.1'};
  const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.box}"/></svg>`;
  const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const fmt=n=>new Intl.NumberFormat('en-GB').format(n);
  const date=(s,time=false)=>new Date(s).toLocaleString('en-GB',{day:'2-digit',month:'short',year:'numeric',...(time?{hour:'2-digit',minute:'2-digit'}:{}),timeZone:'Europe/Prague'});
  const labels={open:'Open',in_progress:'In progress',resolved:'Resolved'};
  const pageNames={overview:'Overview',findings:'Findings',coverage:'Audit coverage',resources:'Resources',compliance:'Compliance',audits:'Audits & reports',team:'Team & XP',activity:'Activity',settings:'Settings'};
  let data=VX.load(localStorage),page='overview',mobile=false,toastTimer,returnFocus,scan=null;
  let filters={query:'',severity:'all',domain:'all',status:'active',assignee:'all',tab:'all',page:1};
  let inventory={query:'',type:'all',page:1},range=30;
  const checks=VX.domains.reduce((s,d)=>s+d.checks,0);
  const member=id=>data.members.find(m=>m.id===id);
  const domain=id=>VX.domains.find(d=>d.id===id);
  const active=()=>VX.open(data);
  const teamXP=()=>data.members.reduce((s,m)=>s+VX.memberXP(data,m.id),0);
  function save(){try{localStorage.setItem(VX.KEY,JSON.stringify(data));}catch{toast('Browser storage is unavailable. Keep this tab open to retain changes.',true);}}
  function avatar(id,size=''){const m=member(id);return m?`<span class="avatar ${esc(m.color)} ${size}">${esc(m.initials)}</span>`:`<span class="avatar unassigned ${size}">${icon('users')}</span>`;}
  const severity=s=>`<span class="severity ${s}"><span class="severity-dot"></span>${s.charAt(0).toUpperCase()+s.slice(1)}</span>`;
  const status=s=>`<span class="status ${s}">${icon(s==='resolved'?'checkCircle':s==='in_progress'?'clock':'alert')}${labels[s]}</span>`;
  const xp=(n,plus=false)=>`<span class="xp-tag">${icon('spark')}${plus?'+':''}${fmt(n)} XP</span>`;
  const link=(href,text)=>`<a class="text-link" href="#${href}">${text}${icon('arrow')}</a>`;
  const button=(action,text,ic,primary=false,extra='')=>`<button class="btn ${primary?'btn-primary':'btn-quiet'}" data-action="${action}" ${extra}>${icon(ic)}${text}</button>`;
  const runButton=()=>button('audit',scan?'Audit running':'Run audit',scan?'refresh':'play',true);
  const progress=(v,cls='')=>`<div class="progress-track"><div class="progress-fill ${cls}" style="width:${Math.min(100,Math.max(0,v))}%"></div></div>`;
  const areaScore=id=>Math.max(0,Math.round((domain(id).checks-data.findings.filter(f=>f.domain===id&&f.status!=='resolved').length*4.5)/domain(id).checks*100));
  function heading(title,subtitle,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`;}
  function navItem(id,ic,label){return `<a href="#${id}" class="nav-item ${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(ic)}${label}${id==='findings'?`<span class="nav-count">${active().length}</span>`:id==='team'?'<span class="nav-new">XP</span>':''}</a>`;}
  function render(){
    document.title=`${pageNames[page]} · Vexorion`;
    document.getElementById('app').innerHTML=`${mobile?'<div class="mobile-shade" data-action="mobile"></div>':''}<aside class="sidebar ${mobile?'mobile-open':''}">
      <a href="#overview" class="brand" aria-label="Vexorion overview"><svg viewBox="0 0 34 35" fill="none" aria-hidden="true"><path d="M2 4h8l7 16L24 4h8L17 34 2 4Z" fill="#a9f078"/><path d="m21 10 3-6h8L21 26l-4-6 4-10Z" fill="#5cdbc0"/></svg><div>VEXORION<div class="brand-sub">AZURE AUDIT PLATFORM</div></div></a>
      <button class="workspace-switch" data-action="workspace"><span class="workspace-icon">A</span><span><strong>${esc(data.settings.organization)}</strong><small>Azure workspace</small></span>${icon('down')}</button>
      <div class="nav-label">WORKSPACE</div><nav class="nav" aria-label="Workspace">${navItem('overview','grid','Overview')}${navItem('findings','shield','Findings')}${navItem('coverage','layers','Audit coverage')}${navItem('resources','box','Resources')}${navItem('compliance','checkCircle','Compliance')}</nav>
      <div class="nav-label">OPERATIONS</div><nav class="nav" aria-label="Operations">${navItem('audits','file','Audits & reports')}${navItem('team','trophy','Team & XP')}${navItem('activity','activity','Activity')}</nav>
      <div class="sidebar-bottom"><nav class="nav" style="margin-bottom:15px" aria-label="Support">${navItem('settings','settings','Settings')}<button class="nav-item" data-action="help">${icon('help')}Help & documentation${icon('external')}</button></nav>
      <div class="connection-card"><div class="connection-top">${icon('cloud')}Microsoft Azure<span class="demo-label">DEMO</span></div><p>Production workspace<br>1 subscription · West Europe</p><a href="#settings">Manage environment${icon('arrow')}</a></div>
      <a href="#team" class="sidebar-profile">${avatar('alex')}<div><strong>Alex Morgan</strong><small>${VX.level(VX.memberXP(data,'alex')).name} · Level ${VX.level(VX.memberXP(data,'alex')).n}</small></div>${icon('down')}</a></div>
      </aside><div class="app-main"><header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-toggle" data-action="mobile" aria-label="Open navigation">${icon('menu')}</button>${icon('home')}<span class="slash">/</span><span class="workspace-crumb">Workspace</span><span class="slash">/</span><strong>${pageNames[page]}</strong></div>
      <div class="topbar-right"><button class="search-trigger" data-action="search" aria-label="Search workspace">${icon('search')}<span>Search anything…</span><kbd>⌘ K</kbd></button><span class="vertical-line"></span><button class="environment" data-action="workspace"><span class="dot"></span>Production<span class="muted">/ Demo</span>${icon('down')}</button><button class="icon-btn" data-action="notifications" aria-label="Notifications">${icon('bell')}${data.settings.notifications?'<span class="notification-dot"></span>':''}</button><a href="#team" class="top-avatar" aria-label="Alex Morgan profile">${avatar('alex')}</a></div></header>
      <main class="content" id="main-content">${scan?`<div class="busy-bar"><span>${icon('refresh','spin')}Demo audit running · ${scan.percent}% complete</span><button class="text-link" data-action="scan-progress">View progress ${icon('arrow')}</button></div>`:''}${renderPage()}
      <footer class="footer"><span>VEXORION<span class="muted">/</span>A clearer cloud. A stronger team.</span><span>${icon('lock')}Local workspace · Sample Azure data</span><span><span class="dot"></span>Demo mode<a href="#settings">v2.0</a></span></footer></main></div>`;
    bindPage();
  }
  function renderPage(){return ({overview,findings:findingsPage,coverage:coveragePage,resources:resourcesPage,compliance:compliancePage,audits:auditsPage,team:teamPage,activity:activityPage,settings:settingsPage}[page]||overview)();}
  function sparkline(color,variant=0){return `<svg class="metric-spark" viewBox="0 0 90 35" fill="none" aria-hidden="true"><path d="${variant?'M1 5l9 6 9-3 10 9 9-5 10 9 10-1 10 7 9-4 12 7':'M1 29l9-5 9 3 10-10 9 4 10-9 10 3 10-8 9 1 12-6'}" stroke="${color}" stroke-width="1.6"/><path d="M1 34h89" stroke="${color}" opacity=".1"/></svg>`;}
  function metrics(){const a=active(),resolved=data.findings.length-a.length,total=teamXP();return `<section class="metrics" aria-label="Workspace metrics">
    <button class="metric metric-featured" data-action="score"><div class="metric-top">${icon('shield','mint')}Security score${icon('external')}</div><div class="metric-value">${VX.score(data)}<small>/ 100</small></div>${sparkline('#a9f078')}<div class="metric-footer"><span class="mint">↗ +8 points</span><span>in demo history</span></div></button>
    <button class="metric" data-action="go-findings"><div class="metric-top">${icon('alert','red')}Open findings${icon('external')}</div><div class="metric-value">${a.length}<small>to resolve</small></div>${sparkline('#ff7988',1)}<div class="metric-footer"><span class="red">${a.filter(f=>f.severity==='critical').length} critical</span><span>· ${a.filter(f=>f.severity==='high').length} high priority</span></div></button>
    <a class="metric" href="#resources"><div class="metric-top">${icon('box','blue')}Resources audited${icon('external')}</div><div class="metric-value">${fmt(VX.resources.length)}</div>${sparkline('#89b7ff')}<div class="metric-footer"><span class="aqua">${icon('checkCircle')} All resources scanned</span><span>· 1 subscription</span></div></a>
    <a class="metric" href="#team"><div class="metric-top">${icon('spark','purple')}Team experience${icon('external')}</div><div class="metric-value">${fmt(total)}<small>XP</small></div>${sparkline('#a99bf6')}<div class="metric-footer"><span class="purple">${resolved} findings resolved</span><span>· ${data.members.length} engineers</span></div></a></section>`;}
  function ring(){const score=VX.score(data);return `<div class="score-ring" role="img" aria-label="Security score ${score} out of 100"><svg viewBox="0 0 180 180"><circle class="ring-track" cx="90" cy="90" r="73" fill="none" stroke-width="8"/><circle class="ring-fill" cx="90" cy="90" r="73" fill="none" stroke-width="8" stroke-dasharray="${score*4.587} 459"/><circle class="ring-inner" cx="90" cy="90" r="60" fill="none" stroke-width="1"/></svg><div class="ring-center"><div class="ring-number">${score}<small> /100</small></div><div class="ring-label">${icon('shield')}${score>=85?'Strong posture':'Looking stronger'}</div><div class="ring-sub">Keep closing the gaps.</div></div></div>`;}
  function chart(){const short=range===7;return `<div class="chart-container"><div class="chart-legend"><span><span class="dot"></span>Security score</span><span class="chart-growth">${icon('up')}+${short?'3':'8'} points</span></div><svg class="chart-svg" viewBox="0 0 330 110" preserveAspectRatio="none" role="img" aria-label="Illustrative ${range}-day security score trend"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#a9f078" stop-opacity=".16"/><stop offset="1" stop-color="#a9f078" stop-opacity="0"/></linearGradient></defs><path d="M0 12H330 M0 44H330 M0 76H330 M0 108H330" stroke="#29323c" stroke-width=".6" stroke-dasharray="3 4"/><path d="${short?'M0 79 35 75 65 82 95 62 125 66 155 50 185 45 215 54 250 28 285 32 320 14':'M0 93 25 89 50 93 78 76 102 81 130 61 155 65 180 45 204 49 230 29 255 32 280 19 300 23 320 9'} L320 110H0Z" fill="url(#chart-fill)"/><path d="${short?'M0 79 35 75 65 82 95 62 125 66 155 50 185 45 215 54 250 28 285 32 320 14':'M0 93 25 89 50 93 78 76 102 81 130 61 155 65 180 45 204 49 230 29 255 32 280 19 300 23 320 9'}" stroke="#a9f078" stroke-width="1.8" fill="none" stroke-linejoin="round"/><circle cx="320" cy="${short?14:9}" r="4" fill="#a9f078" stroke="#263525" stroke-width="5"/><text x="331" y="16" fill="#718095" font-size="7" text-anchor="end">100</text><text x="331" y="106" fill="#718095" font-size="7" text-anchor="end">0</text></svg><div class="chart-labels">${(short?['07 Nov','09 Nov','11 Nov','13 Nov']:['15 Oct','22 Oct','29 Oct','05 Nov','13 Nov']).map(s=>`<span>${s}</span>`).join('')}</div></div>`;}
  function overview(){return `${heading('Azure command center','See the risks. Own the fix. Make progress that counts.',`${button('export','Export report','download')}${runButton()}`)}${metrics()}
      <div class="dashboard-main"><section class="panel posture-panel"><div class="panel-head"><div><h2>Cloud security posture</h2><p>A healthier environment, one resolution at a time.</p></div><div class="segmented" aria-label="Chart date range"><button data-action="range" data-value="7" class="${range===7?'selected':''}" aria-pressed="${range===7}">7 days</button><button data-action="range" data-value="30" class="${range===30?'selected':''}" aria-pressed="${range===30}">30 days</button></div></div><div class="posture-body">${ring()}${chart()}</div><div class="posture-caption">${icon('checkCircle')}Last demo audit: ${date(data.lastAudit,true)}${link('audits','View audit history')}</div></section>
      <section class="panel coverage-panel"><div class="panel-head"><div><h2>Audit coverage <span class="count-pill">18 areas</span></h2><p>No blind spots left behind.</p></div>${link('coverage','Explore all')}</div><div class="coverage-list">${['identity','network','compute','data'].map((id,i)=>`<button class="coverage-item" data-action="domain" data-id="${id}"><span class="domain-icon ${['','purple','blue','amber'][i]}">${icon(domain(id).icon)}</span><div class="coverage-info"><div class="coverage-meta"><span class="coverage-name">${domain(id).name}</span><small>${areaScore(id)}%</small></div>${progress(areaScore(id),['','purple','blue','aqua'][i])}</div></button>`).join('')}</div><div class="coverage-bottom"><span>${icon('checkCircle')}${checks} checks in the demo catalog</span>${link('coverage','+14 more areas')}</div></section></div>
      ${priorityTable()}<div class="dashboard-bottom">${levelCard()}${leaderboard()}<section class="panel activity-panel"><div class="panel-head"><h2>Recent activity</h2>${link('activity','View all')}</div><div class="activity-list">${data.activity.slice(0,3).map(activityItem).join('')}</div></section></div>`;}
  function filteredFindings(){return data.findings.filter(f=>{
    const q=filters.query.toLowerCase();
    return (!q||`${f.id} ${f.title} ${f.resource} ${domain(f.domain).name}`.toLowerCase().includes(q))&&(filters.severity==='all'||f.severity===filters.severity)&&(filters.domain==='all'||f.domain===filters.domain)&&(filters.status==='all'||filters.status==='active'&&f.status!=='resolved'||f.status===filters.status)&&(filters.assignee==='all'||filters.assignee==='unassigned'&&!f.assignee||f.assignee===filters.assignee)&&(filters.tab!=='mine'||f.assignee==='alex')&&(filters.tab!=='unassigned'||!f.assignee);
    }).sort((a,b)=>VX.XP[b.severity]-VX.XP[a.severity]||a.id.localeCompare(b.id));}
  function findingRows(fs){return fs.map(f=>`<tr><td><button class="finding-title" data-action="finding" data-id="${f.id}">${esc(f.title)}</button><div class="finding-sub">${f.id}<span>·</span>${esc(f.resource)}</div></td><td>${severity(f.severity)}</td><td><span class="muted">${esc(domain(f.domain).name)}</span></td><td><button class="assignee" data-action="assign" data-id="${f.id}" aria-label="Assign ${f.id}">${avatar(f.assignee,'small')}${esc(member(f.assignee)?.name.split(' ')[0]||'Unassigned')}</button></td><td>${status(f.status)}</td><td>${xp(VX.XP[f.severity],true)}</td><td><button class="icon-btn" data-action="finding" data-id="${f.id}" aria-label="Open ${f.id}">${icon('right')}</button></td></tr>`).join('');}
  function findingTable(fs){return `<div class="table-wrap"><table><thead><tr><th>Finding</th><th>Severity</th><th>Audit area</th><th>Assigned to</th><th>Status</th><th>Reward</th><th><span class="sr-only">Details</span></th></tr></thead><tbody>${fs.length?findingRows(fs):'<tr><td colspan="7"><div class="empty">'+icon('checkCircle')+'<h3>All clear here.</h3><p>No findings match your current filters.</p></div></td></tr>'}</tbody></table></div>`;}
  function tabs(){return `<div class="tabs" role="tablist" aria-label="Finding ownership"><button class="tab ${filters.tab==='all'?'selected':''}" data-action="tab" data-value="all" role="tab" aria-selected="${filters.tab==='all'}">All findings <small>${active().length}</small></button><button class="tab ${filters.tab==='mine'?'selected':''}" data-action="tab" data-value="mine" role="tab" aria-selected="${filters.tab==='mine'}">Assigned to me <small>${active().filter(f=>f.assignee==='alex').length}</small></button><button class="tab ${filters.tab==='unassigned'?'selected':''}" data-action="tab" data-value="unassigned" role="tab" aria-selected="${filters.tab==='unassigned'}">Unassigned <small>${active().filter(f=>!f.assignee).length}</small></button></div>`;}
  function priorityTable(){const fs=filteredFindings().filter(f=>f.status!=='resolved');return `<section class="panel priority"><div class="panel-head"><div><h2>Findings that need you <span class="count-pill">${active().length}</span></h2><p>Your highest-impact fixes, ready to take on.</p></div><div class="panel-actions">${button('filter','Filters','filter')}${link('findings','View all findings')}</div></div>${tabs()}${findingTable(fs.slice(0,4))}<div class="table-foot"><span>Showing ${Math.min(fs.length,4)} of ${fs.length} active findings</span><span>${icon('spark','mint')} Every fix makes a difference.</span></div></section>`;}
  function levelCard(){const total=VX.memberXP(data,'alex'),l=VX.level(total),percentage=(total-l.min)/(l.max-l.min)*100;return `<section class="panel level-card"><div class="eyebrow">YOUR NEXT CHAPTER</div><h2>${l.name} in the making.</h2><p>Turn cloud improvements into personal achievements.</p><span class="level-emblem">${icon('shield')}</span><div class="level-progress-label"><strong>Level ${l.n} · ${l.name}</strong><span>${fmt(total)} / ${fmt(l.max)} XP</span></div>${progress(percentage)}${link('team','Keep the momentum going')}</section>`;}
  function leaderboard(){return `<section class="panel"><div class="panel-head"><h2>${icon('trophy','purple')}Team leaderboard</h2>${link('team','View team')}</div><div class="leader-list">${[...data.members].sort((a,b)=>VX.memberXP(data,b.id)-VX.memberXP(data,a.id)).slice(0,3).map((m,i)=>`<div class="leader-row"><span class="rank ${i===0?'first':''}">${String(i+1).padStart(2,'0')}</span>${avatar(m.id,'small')}<span class="leader-name">${esc(m.name)}${m.id==='alex'?'<small>you</small>':''}</span>${xp(VX.memberXP(data,m.id))}</div>`).join('')}</div></section>`;}
  function activityItem(a){return `<div class="activity-item"><span class="activity-dot">${icon(a.member?'check':'refresh')}</span><div><strong>${esc(a.title)}</strong><small>${esc(a.detail)}<br>${date(a.at,true)}</small></div></div>`;}
  function options(items,value){return items.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('');}
  function findingsPage(){const fs=filteredFindings(),size=10,pages=Math.max(1,Math.ceil(fs.length/size));filters.page=Math.min(filters.page,pages);return `${heading('Findings','A clear path from discovery to resolution.',`${button('export-csv','Export CSV','download')}${runButton()}`)}${metrics()}<section class="panel"><div class="panel-head"><h2>All findings <span class="count-pill">${data.findings.length}</span></h2><span class="note">Resolve. Verify. Earn XP.</span></div><div class="filters"><label class="input-wrap">${icon('search')}<input id="finding-search" value="${esc(filters.query)}" placeholder="Search findings, resources, IDs…" aria-label="Search findings"></label><select id="severity-filter" aria-label="Filter by severity">${options([['all','All severities'],...Object.keys(VX.XP).map(s=>[s,s[0].toUpperCase()+s.slice(1)])],filters.severity)}</select><select id="domain-filter" aria-label="Filter by audit area">${options([['all','All audit areas'],...VX.domains.map(d=>[d.id,d.name])],filters.domain)}</select><select id="status-filter" aria-label="Filter by status">${options([['active','Active findings'],['all','All statuses'],...Object.entries(labels)],filters.status)}</select><select id="assignee-filter" aria-label="Filter by assignee">${options([['all','All engineers'],['unassigned','Unassigned'],...data.members.map(m=>[m.id,m.name])],filters.assignee)}</select></div>${tabs()}<div id="findings-results">${findingTable(fs.slice((filters.page-1)*size,filters.page*size))}${pagination('findings',filters.page,pages,fs.length,size)}</div></section>`;}
  function pagination(kind,current,total,count,size){return `<div class="table-foot"><span>${count?`${(current-1)*size+1}–${Math.min(current*size,count)}`:'0'} of ${fmt(count)} ${kind==='findings'?'findings':'resources'}</span><div class="pagination"><button class="btn btn-quiet" data-action="paginate" data-kind="${kind}" data-value="${current-1}" ${current<=1?'disabled':''}>${icon('left')}Previous</button><span>${current} / ${total}</span><button class="btn btn-quiet" data-action="paginate" data-kind="${kind}" data-value="${current+1}" ${current>=total?'disabled':''}>Next${icon('right')}</button></div></div>`;}
  function coveragePage(){return `${heading('Every angle. Audited.','18 audit areas. One comprehensive view of your Azure environment.',runButton())}<div class="panel coverage-intro">${icon('layers')}<div><strong>${checks} illustrative checks across security, operations and architecture</strong><p>The demo catalog draws on the <a href="https://learn.microsoft.com/en-us/security/benchmark/azure/" target="_blank" rel="noopener noreferrer">Microsoft cloud security benchmark</a> and <a href="https://learn.microsoft.com/en-us/azure/well-architected/" target="_blank" rel="noopener noreferrer">Azure Well-Architected Framework</a>. Scores and checks use sample data; this is not a certification.</p></div></div><section class="domain-grid" aria-label="Audit areas">${VX.domains.map((d,i)=>{const count=active().filter(f=>f.domain===d.id).length;return `<article class="panel domain-card"><div class="domain-card-top"><span class="domain-icon ${['','purple','blue','amber'][i%4]}">${icon(d.icon)}</span>${count?`<span class="tag">${count} open ${count===1?'finding':'findings'}</span>`:`<span class="status-indicator">${icon('checkCircle')}All clear</span>`}</div><h3>${d.name}</h3><p>${d.description}</p><div class="domain-card-stats"><span>${d.checks} checks</span><span class="${areaScore(d.id)>=85?'aqua':'amber'}">${areaScore(d.id)}% posture score</span></div>${progress(areaScore(d.id),['','purple','blue','aqua'][i%4])}<div class="domain-card-bottom"><span>${icon('checkCircle')} Audit ready</span><button class="text-link" data-action="domain" data-id="${d.id}">View findings${icon('arrow')}</button></div></article>`;}).join('')}</section>`;}
  function filteredResources(){return VX.resources.filter(r=>(inventory.type==='all'||inventory.type===r.type)&&`${r.name} ${r.type} ${r.group} ${r.region}`.toLowerCase().includes(inventory.query.toLowerCase()));}
  function resourceResults(){const rs=filteredResources(),size=15,pages=Math.max(1,Math.ceil(rs.length/size));inventory.page=Math.min(inventory.page,pages);return `<div class="table-wrap"><table><thead><tr><th>Resource name</th><th>Type</th><th>Resource group</th><th>Region</th><th>Audit status</th><th></th></tr></thead><tbody>${rs.length?rs.slice((inventory.page-1)*size,inventory.page*size).map(r=>`<tr><td><button class="finding-title" data-action="resource" data-id="${r.id}">${icon('box','blue')} ${esc(r.name)}</button></td><td class="muted">${r.type}</td><td class="muted mono">${r.group}</td><td class="muted">${r.region}</td><td><span class="resource-risk">${icon('checkCircle')}Scanned</span></td><td><button class="icon-btn" data-action="resource" data-id="${r.id}" aria-label="View ${esc(r.name)}">${icon('right')}</button></td></tr>`).join(''):'<tr><td colspan="6"><div class="empty">'+icon('search')+'<h3>No resources found</h3><p>Try a different name, type or region.</p></div></td></tr>'}</tbody></table></div>${pagination('resources',inventory.page,pages,rs.length,size)}`;}
  function resourcesPage(){return `${heading('Your Azure universe.','A searchable inventory of every resource in this demo subscription.',button('export-resources','Export inventory','download'))}<section class="panel"><div class="panel-head"><div><h2>Resource inventory <span class="count-pill">${fmt(VX.resources.length)}</span></h2><p>Production · 1 subscription · 3 regions</p></div><span class="tag">Sample inventory</span></div><div class="filters"><label class="input-wrap">${icon('search')}<input id="resource-search" value="${esc(inventory.query)}" placeholder="Search resources, groups or regions…" aria-label="Search resources"></label><select id="resource-type" aria-label="Filter resource type">${options([['all','All resource types'],...[...new Set(VX.resources.map(r=>r.type))].map(t=>[t,t])],inventory.type)}</select></div><div id="resource-results">${resourceResults()}</div></section>`;}
  function compliancePage(){const frameworks=[['Microsoft cloud security benchmark','Security controls across your Azure environment.','MCSB'],['CIS Azure Foundations','A practical baseline for cloud configuration hygiene.','CIS'],['ISO 27001','Illustrative links between findings and security controls.','ISO']];return `${heading('Evidence over assumptions.','Track control coverage and keep your next review in sight.',button('export','Export evidence','download'))}<div class="panel coverage-intro">${icon('info')}<div><strong>Compliance readiness, with context</strong><p>These are illustrative control mappings and sample readiness scores. An audit result is not a compliance certification or a substitute for control-owner evidence.</p></div></div><section class="compliance-grid">${frameworks.map(([name,desc,short],i)=>`<article class="panel framework-card"><div class="framework-icon">${icon(i===0?'shield':i===1?'layers':'file')}</div><h3>${name}</h3><p>${desc}</p><div class="display">${Math.min(100,VX.score(data)+[4,-5,1][i])}<small>%</small></div>${progress(Math.min(100,VX.score(data)+[4,-5,1][i]),i===1?'purple':'aqua')}<div class="note">${short} · Demo control mapping</div></article>`).join('')}</section><section class="panel"><div class="panel-head"><h2>Control evidence register</h2><span class="note">Sample mappings</span></div><div class="table-wrap" style="margin-top:17px"><table><thead><tr><th>Reference</th><th>Finding</th><th>Audit area</th><th>Readiness</th><th></th></tr></thead><tbody>${data.findings.slice(0,14).map(f=>`<tr><td class="mono muted">${esc(f.control)}</td><td><button class="finding-title" data-action="finding" data-id="${f.id}">${esc(f.title)}</button></td><td class="muted">${domain(f.domain).name}</td><td>${status(f.status)}</td><td>${severity(f.severity)}</td></tr>`).join('')}</tbody></table></div></section>`;}
  function auditsPage(){const rows=data.reports;return `${heading('From signal to snapshot.','Run a scoped audit and keep an immutable record of what you found.',runButton())}<div class="panel coverage-intro">${icon('refresh')}<div><strong>A complete workflow, in demo mode</strong><p>Choose audit areas, watch the simulated checks complete, then review and export the saved report. Running an audit does not contact Azure or change any cloud resources.</p></div></div><section class="panel"><div class="panel-head"><h2>Audit history <span class="count-pill">${rows.length}</span></h2><span class="note">Saved in this browser</span></div><div class="table-wrap" style="margin-top:17px"><table><thead><tr><th>Audit</th><th>Completed</th><th>Scope</th><th>Checks</th><th>Open findings</th><th>Report</th></tr></thead><tbody>${rows.length?rows.map(r=>`<tr><td><button class="report-link" data-action="report" data-id="${r.id}">${r.id}</button><div class="finding-sub">Simulated audit · Completed</div></td><td class="muted">${date(r.at,true)}</td><td class="muted">${r.domains.length} audit areas</td><td>${r.checks}</td><td>${r.findings.filter(f=>f.status!=='resolved').length}</td><td><button class="btn btn-quiet" data-action="report" data-id="${r.id}">${icon('file')}View report</button></td></tr>`).join(''):`<tr><td colspan="6"><div class="empty">${icon('file')}<h3>Your next audit starts here.</h3><p>Run a demo audit to create your first saved report.</p><div style="margin-top:20px">${runButton()}</div></div></td></tr>`}</tbody></table></div></section>`;}
  function weekKey(value){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Prague',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date(value));const n=t=>Number(parts.find(p=>p.type===t).value),d=new Date(Date.UTC(n('year'),n('month')-1,n('day')));d.setUTCDate(d.getUTCDate()-(d.getUTCDay()+6)%7);return d.toISOString().slice(0,10);}
  function teamPage(){const mine=data.findings.filter(f=>f.status==='resolved'&&data.ledger[f.id]?.owner==='alex'),week=weekKey(new Date()),weekly=mine.filter(f=>weekKey(data.ledger[f.id].at)===week).length,goal=Number(data.settings.weeklyGoal)||5;return `${heading('Better cloud. Stronger team.','Give every fix an owner. Give every engineer a reason to keep going.',button('add-member','Add engineer','plus'))}<section class="team-grid">${[...data.members].sort((a,b)=>VX.memberXP(data,b.id)-VX.memberXP(data,a.id)).map(m=>{const total=VX.memberXP(data,m.id),l=VX.level(total),resolved=data.findings.filter(f=>f.status==='resolved'&&data.ledger[f.id]?.owner===m.id).length;return `<article class="panel member-card">${avatar(m.id,'large')}<h3>${esc(m.name)}${m.id==='alex'?' <small class="muted">(you)</small>':''}</h3><p class="role">${esc(m.role)}</p><span class="member-level">${icon('shield')}Level ${l.n} · ${l.name}</span><div class="display">${fmt(total)} <small>XP</small></div>${progress((total-l.min)/(l.max-l.min)*100,m.color==='purple'?'purple':m.color==='blue'?'blue':'')}<div class="goal-caption">${fmt(l.max-total)} XP to the next level</div><div class="member-stats"><span><strong>${resolved}</strong> resolved</span><span><strong>${active().filter(f=>f.assignee===m.id).length}</strong> assigned</span></div></article>`;}).join('')}</section><div class="team-lower"><section class="panel"><div class="panel-head"><h2>Your achievements</h2><span class="note">${mine.length} verified resolutions</span></div><div class="achievements">${[['checkCircle','First fix','Resolve your first finding',mine.length>=1],['shield','Risk remover','Resolve a critical finding',mine.some(f=>f.severity==='critical')],['layers','All-rounder','Resolve across 3 audit areas',new Set(mine.map(f=>f.domain)).size>=3]].map(([ic,title,desc,earned])=>`<div class="achievement ${earned?'':'locked'}">${icon(ic)}<strong>${title}</strong><small>${desc}</small></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>Your weekly mission</h2>${link('settings','Edit goal')}</div><div class="week-goal"><div class="display">${weekly}<small> / ${goal} fixes</small></div>${progress(weekly/goal*100)}<p>${weekly>=goal?'Mission complete. Your cloud is better for it.':`${Math.max(0,goal-weekly)} more verified resolutions to reach your goal.`} Resets on Monday, Europe/Prague time.</p>${link('findings','Find your next fix')}</div></section><section class="panel"><div class="panel-head"><h2>The impact behind the XP</h2>${icon('spark','mint')}</div><div class="rules">${Object.entries(VX.XP).map(([s,n])=>`<div class="rule-row">${severity(s)}${xp(n,true)}</div>`).join('')}<p class="note">XP goes to the assigned engineer after remediation is verified. A finding earns credit once. Reopening suspends that credit; resolving it again restores the original credit and owner.</p></div></section>${leaderboard()}</div>`;}
  function activityPage(){return `${heading('Progress leaves a trail.','Audit runs and verified resolutions, in one workspace timeline.')}<section class="panel"><div class="panel-head"><h2>Workspace activity <span class="count-pill">${data.activity.length}</span></h2><span class="note">Browser-local demo</span></div><div class="full-activity">${data.activity.map(activityItem).join('')}</div></section>`;}
  function settingsPage(){return `${heading('Make it your workspace.','Your environment, your team, your way of working.')}<div class="settings-grid"><section class="panel"><div class="panel-head"><h2>Workspace preferences</h2></div><form id="settings-form" class="settings-body"><label class="field">Organization name<input name="organization" value="${esc(data.settings.organization)}" required maxlength="60" autocomplete="organization"></label><label class="field">Your weekly goal<select name="weeklyGoal">${options([['3','3 verified fixes'],['5','5 verified fixes'],['10','10 verified fixes']],String(data.settings.weeklyGoal))}</select><small>A personal goal that resets each Monday in Europe/Prague.</small></label><label class="setting-toggle"><span>Activity notification indicator<small>Show an indicator on the workspace notification button.</small></span><input type="checkbox" name="notifications" ${data.settings.notifications?'checked':''}></label><div>${button('submit-settings','Save preferences','check',true,'type="submit"')}</div></form></section><div><section class="panel"><div class="panel-head"><h2>Azure environment</h2><span class="demo-label">DEMO</span></div><div class="settings-body"><div class="status-box">${icon('cloud')}<div><strong>Production · Sample Azure subscription</strong><p class="note">This frontend runs entirely in your browser. No Azure connection has been configured and no cloud credentials are requested.</p></div></div><div class="field-row"><div class="field">Primary region<strong class="muted">West Europe</strong></div><div class="field">Environment<strong class="muted">Production / Demo</strong></div></div><p class="note">Live auditing needs a backend with Microsoft Entra authentication, authorized read access, scheduled audit workers and a shared database for findings and evidence.</p><button type="button" class="btn btn-quiet" data-action="help">${icon('info')}About this workspace</button></div></section><section class="panel" style="margin-top:20px"><div class="panel-head"><h2>Demo data</h2></div><div class="settings-body"><p class="note">Reset findings, engineer assignments, XP, audit reports and preferences to the original sample workspace.</p><div>${button('reset','Reset demo workspace','refresh',false,'class="btn btn-danger"')}</div></div></section></div></div>`;}
  function bindPage(){
    const findInput=document.getElementById('finding-search');
    findInput?.addEventListener('input',e=>{filters.query=e.target.value;filters.page=1;refreshFindings();});
    [['severity-filter','severity'],['domain-filter','domain'],['status-filter','status'],['assignee-filter','assignee']].forEach(([id,key])=>document.getElementById(id)?.addEventListener('change',e=>{filters[key]=e.target.value;filters.page=1;refreshFindings();}));
    document.getElementById('resource-search')?.addEventListener('input',e=>{inventory.query=e.target.value;inventory.page=1;document.getElementById('resource-results').innerHTML=resourceResults();});
    document.getElementById('resource-type')?.addEventListener('change',e=>{inventory.type=e.target.value;inventory.page=1;document.getElementById('resource-results').innerHTML=resourceResults();});
    document.getElementById('settings-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);data.settings={organization:String(f.get('organization')).trim()||'Acme Technologies',weeklyGoal:Number(f.get('weeklyGoal')),notifications:f.get('notifications')==='on'};save();render();toast('Workspace preferences saved.');});
  }
  function refreshFindings(){const fs=filteredFindings(),pages=Math.max(1,Math.ceil(fs.length/10));filters.page=Math.min(filters.page,pages);document.getElementById('findings-results').innerHTML=findingTable(fs.slice((filters.page-1)*10,filters.page*10))+pagination('findings',filters.page,pages,fs.length,10);}
  function toast(message,error=false){clearTimeout(toastTimer);document.getElementById('toast-root').innerHTML=`<div class="toast ${error?'error':''}" role="status">${icon(error?'alert':'checkCircle')}${esc(message)}</div>`;toastTimer=setTimeout(()=>document.getElementById('toast-root').innerHTML='',4200);}
  function closeOverlay(){document.getElementById('overlay-root').innerHTML='';document.body.style.overflow='';if(returnFocus?.isConnected)returnFocus.focus();}
  function overlay(title,body,footer='',drawer=false,subtitle=''){
    const existing=document.getElementById('overlay-root').children.length;
    if(!existing)returnFocus=document.activeElement;
    document.getElementById('overlay-root').innerHTML=`<div class="modal-backdrop ${drawer?'drawer-backdrop':''}"><section class="modal ${drawer?'drawer':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header class="modal-head"><div><h2 id="dialog-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="icon-btn" data-action="close" aria-label="Close dialog">${icon('x')}</button></header><div class="modal-body">${body}</div>${footer?`<footer class="modal-foot">${footer}</footer>`:''}</section></div>`;
    document.body.style.overflow='hidden';
    const focus=document.querySelector('.modal [autofocus]')||document.querySelector('.modal button,.modal input,.modal select');focus?.focus();
  }
  function openFinding(id){const f=data.findings.find(f=>f.id===id);if(!f)return;const credited=data.ledger[id];overlay(`<div class="detail-id">${f.id} / ${esc(domain(f.domain).name)}</div><div class="detail-title">${esc(f.title)}</div><div class="detail-badges">${severity(f.severity)}${status(f.status)}${xp(VX.XP[f.severity],true)}</div>`,
    `<section class="detail-section"><h3>Why it matters</h3><p>${esc(f.description)}</p></section><section class="detail-section"><h3>Affected resource</h3><div class="detail-resource">${icon('box')}<span class="mono">${esc(f.resource)}</span><span class="tag" style="margin-left:auto">Production</span></div></section><section class="detail-section"><h3>${icon('shield')}Recommended remediation</h3><div class="remediation-box"><p>${esc(f.remediation)}</p></div><p class="note" style="margin-top:9px">Sample guidance · Validate applicability and dependencies before changing a live environment.</p></section><section class="detail-section"><h3>Control reference</h3><span class="tag">${esc(f.control)}</span><p class="note" style="margin-top:9px">Detected ${date(f.detected,true)} · Sample audit evidence</p></section><form id="finding-form" class="detail-ownership"><div class="field-row"><label class="field">Assigned engineer<select name="assignee">${options([['','Unassigned'],...data.members.map(m=>[m.id,m.name+(m.id==='alex'?' (you)':'')])],f.assignee||'')}</select></label><label class="field">Finding status<select name="status">${options(Object.entries(labels),f.status)}</select></label></div><label class="verify-check"><input type="checkbox" name="verified"><span>I have reviewed and verified the remediation for this finding.</span></label><div class="xp-banner">${icon('spark')}<div>${credited?`Original credit: ${fmt(credited.xp)} XP · ${esc(member(credited.owner)?.name||'Original engineer')}`:`A verified fix earns ${VX.XP[f.severity]} XP`}<small>${credited?'Reopening suspends XP. Re-resolving restores the original credit.':'Rewarded to the assigned engineer, once per finding.'}</small></div></div><p class="form-error" id="finding-error" role="alert"></p></form>`,
    `${button('close','Cancel','x')}<button class="btn btn-primary" form="finding-form" type="submit">${icon('check')}Save changes</button>`,true);
    document.getElementById('finding-form').addEventListener('submit',e=>{e.preventDefault();const fields=new FormData(e.target),prev=f.status;try{const result=VX.update(data,id,{assignee:fields.get('assignee'),status:fields.get('status'),verified:fields.get('verified')==='on'});save();closeOverlay();render();toast(result.awarded?`Finding resolved. +${result.awarded} XP for ${member(f.assignee).name}!`:prev==='resolved'&&f.status!=='resolved'?'Finding reopened. Original XP suspended.':'Finding updated.');}catch(error){document.getElementById('finding-error').textContent=error.message;}});
  }
  function openAssignment(id){const f=data.findings.find(f=>f.id===id);if(!f)return;overlay('Give this fix an owner.',`<p class="note" style="margin-bottom:17px">${id} · ${esc(f.title)}</p>${[null,...data.members].map(m=>`<button class="member-choice" data-action="choose-assignee" data-id="${id}" data-value="${m?.id||''}">${avatar(m?.id)}<span><strong>${esc(m?.name||'Unassigned')}${m?.id==='alex'?' (you)':''}</strong><small>${esc(m?.role||'Leave this finding available to the team')}</small></span>${f.assignee===(m?.id||null)?icon('check'):''}</button>`).join('')}`,`${button('add-member','Add engineer','plus')}${button('close','Done','check')}`);}
  function auditModal(){if(scan){showScan();return;}overlay('Look closer. Find what matters.',`<div class="status-box">${icon('cloud')}<div><strong>Production · Demo subscription</strong><p class="note">A simulated audit of 1,248 sample resources. No Azure connection is used.</p></div></div><div class="scope-summary" style="margin-top:22px"><span>Select audit areas</span><button class="select-all" data-action="select-scope">Select / clear all</button></div><div class="scope-grid">${VX.domains.map(d=>`<label class="scope-choice"><input type="checkbox" name="audit-scope" value="${d.id}" checked>${d.name}</label>`).join('')}</div><div class="scope-summary" style="margin:18px 0 0"><span id="scope-count">18 areas · ${checks} checks selected</span><span>Estimated time: ~8 seconds</span></div><p id="scope-error" class="form-error" role="alert"></p>`,`${button('close','Cancel','x')}${button('start-audit','Start demo audit','play',true)}`,'','Choose the scope. We’ll collect the findings in a saved report.');document.querySelectorAll('[name="audit-scope"]').forEach(el=>el.addEventListener('change',scopeCount));}
  function scopeCount(){const ids=[...document.querySelectorAll('[name="audit-scope"]:checked')].map(e=>e.value);document.getElementById('scope-count').textContent=`${ids.length} areas · ${VX.domains.filter(d=>ids.includes(d.id)).reduce((s,d)=>s+d.checks,0)} checks selected`;}
  function startAudit(){const ids=[...document.querySelectorAll('[name="audit-scope"]:checked')].map(el=>el.value);if(!ids.length){document.getElementById('scope-error').textContent='Select at least one audit area.';return;}scan={ids,percent:0,started:Date.now(),token:crypto.randomUUID()};render();showScan();const token=scan.token;const interval=setInterval(()=>{if(!scan||scan.token!==token){clearInterval(interval);return;}scan.percent=Math.min(100,scan.percent+8);if(scan.percent>=100){clearInterval(interval);const r=VX.snapshot(data,scan.ids);data.reports.unshift(r);data.lastAudit=r.at;data.activity.unshift({title:`Demo audit ${r.id} completed`,detail:`${r.domains.length} areas · ${r.checks} checks · ${r.findings.filter(f=>f.status!=='resolved').length} open findings`,at:r.at,member:null});scan=null;save();const visible=!!document.getElementById('scan-content');render();if(visible)openReport(r.id);toast(`Audit complete. ${r.id} is ready to review.`);}else{if(document.getElementById('scan-content'))updateScan();const busy=document.querySelector('.busy-bar>span');if(busy)busy.innerHTML=`${icon('refresh','spin')}Demo audit running · ${scan.percent}% complete`;}},550);}
  function scanBody(){if(!scan)return '';const done=Math.min(scan.ids.length,Math.floor(scan.percent/100*scan.ids.length));return `<div id="scan-content"><div class="scan-visual">${icon('shield')}</div><h3 class="scan-title">Bringing your cloud into focus.</h3><p class="scan-detail">${scan.percent<25?'Discovering sample resources…':scan.percent<80?`Evaluating ${esc(domain(scan.ids[Math.min(done,scan.ids.length-1)]).name)}…`:'Collecting evidence and preparing your report…'}</p><div class="scan-progress">${progress(scan.percent)}</div><div class="scope-summary"><span>Simulated audit · ${done} / ${scan.ids.length} areas</span><span class="scan-percentage">${scan.percent}%</span></div><div class="scan-checks">${scan.ids.slice(Math.max(0,done-3),Math.max(4,done+1)).map((id,i)=>`<div class="scan-check"><span>${icon(scan.ids.indexOf(id)<done?'checkCircle':'clock')}${domain(id).name}</span><span>${scan.ids.indexOf(id)<done?'Complete':'Checking'}</span></div>`).join('')}</div></div>`;}
  function showScan(){if(!scan)return;overlay('Audit in progress',scanBody(),button('close','Continue in background','arrow'),false,'You can keep working while the demo checks run.');}
  function updateScan(){const e=document.getElementById('scan-content');if(e)e.outerHTML=scanBody();}
  function openReport(id){const r=data.reports.find(r=>r.id===id);if(!r)return;overlay(`Audit report / ${r.id}`,`<div class="report-summary"><div><strong>${r.domains.length}</strong><small>audit areas</small></div><div><strong>${r.checks}</strong><small>checks completed</small></div><div><strong class="amber">${r.findings.filter(f=>f.status!=='resolved').length}</strong><small>open findings</small></div></div><p class="note">Completed ${date(r.at,true)} · ${fmt(r.resources)} sample resources. This report preserves statuses and assignees as they were at completion.</p><h3 style="font-size:12px;margin:22px 0 9px">Findings snapshot <span class="count-pill">${r.findings.length}</span></h3><div class="report-findings">${r.findings.length?r.findings.map(f=>`<div class="search-result">${icon('shield','muted')}<span><strong>${esc(f.title)}</strong><small>${f.id} · ${esc(f.assigneeName)} · ${labels[f.status]}</small></span>${severity(f.severity)}</div>`).join(''):'<p class="note">No findings in the selected audit areas.</p>'}</div>`,`${button('close','Close','x')}${button('download-report','Download report','download',true,`data-id="${r.id}"`)}`,false,'Simulated Azure audit · Saved report snapshot');}
  function download(name,text,type){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function csvCell(v){let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}
  function exportCSV(rows,filename='vexorion-findings.csv'){const values=[['ID','Finding','Severity','Audit area','Resource','Status','Assigned engineer'],...rows.map(f=>[f.id,f.title,f.severity,domain(f.domain).name,f.resource,labels[f.status],f.assigneeName||member(f.assignee)?.name||'Unassigned'])];download(filename,'\uFEFF'+values.map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8');toast('Findings exported.');}
  function exportHTML(r){const html=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Vexorion / ${esc(r.id)}</title><style>body{font:14px system-ui;color:#182123;max-width:1100px;margin:60px auto;padding:0 25px}h1{font-size:36px;letter-spacing:-1px}p{color:#54626b;line-height:1.7}table{border-collapse:collapse;width:100%;font-size:12px;margin-top:35px}th,td{text-align:left;padding:13px 10px;border-bottom:1px solid #dae1e3;vertical-align:top}th{background:#f0f4f2}.brand{letter-spacing:3px;font-size:13px;color:#35643c}small{color:#68777c}@media print{body{margin:0;padding:0}tr{break-inside:avoid}}</style></head><body><div class="brand">VEXORION / AZURE AUDIT PLATFORM</div><h1>Azure audit report</h1><p>${esc(r.id)} · ${date(r.at,true)}<br>${r.domains.length} audit areas · ${r.checks} illustrative checks · ${fmt(r.resources)} sample resources</p><p><strong>${r.findings.filter(f=>f.status!=='resolved').length} open findings</strong> / ${r.findings.length} total findings in scope</p><p>Audit scope: ${r.domains.map(id=>esc(domain(id).name)).join(', ')}</p><table><thead><tr><th>Finding</th><th>Severity</th><th>Area</th><th>Resource</th><th>Owner</th><th>Status</th></tr></thead><tbody>${r.findings.map(f=>`<tr><td><small>${f.id}</small><br>${esc(f.title)}</td><td>${f.severity}</td><td>${esc(domain(f.domain).name)}</td><td>${esc(f.resource)}</td><td>${esc(f.assigneeName||member(f.assignee)?.name||'Unassigned')}</td><td>${labels[f.status]}</td></tr>`).join('')}</tbody></table><p><small>Browser-local frontend demonstration. All cloud data, checks and evidence are simulated. This report is not a compliance certification. XP does not form part of audit evidence. Use your browser’s Print function to save as PDF.</small></p></body></html>`;download(`vexorion-${r.id.toLowerCase()}.html`,html,'text/html;charset=utf-8');toast('Audit report downloaded. Open it to print or save as PDF.');}
  function globalSearch(){overlay('Search your workspace',`<label class="input-wrap">${icon('search')}<input id="global-search" placeholder="Find findings, audit areas, pages…" aria-label="Search workspace" autofocus></label><div id="search-results" style="margin-top:12px">${searchResults('')}</div>`,'',false,'Jump straight to what needs your attention.');document.getElementById('global-search').addEventListener('input',e=>document.getElementById('search-results').innerHTML=searchResults(e.target.value));}
  function searchResults(query){const q=query.toLowerCase().trim(),fs=data.findings.filter(f=>`${f.id} ${f.title} ${f.resource}`.toLowerCase().includes(q)).slice(0,5),ds=VX.domains.filter(d=>d.name.toLowerCase().includes(q)).slice(0,3);return `${q?'':'<div class="search-section">QUICK ACCESS</div>'}${!q?['findings','coverage','team'].map(p=>`<a class="search-result" data-action="close" href="#${p}">${icon(p==='team'?'trophy':p==='coverage'?'layers':'shield')}<span><strong>${pageNames[p]}</strong></span>${icon('arrow')}</a>`).join(''):''}${fs.length?'<div class="search-section">FINDINGS</div>':''}${fs.map(f=>`<button class="search-result" data-action="finding" data-id="${f.id}">${icon('shield','muted')}<span><strong>${esc(f.title)}</strong><small>${f.id} · ${esc(f.resource)}</small></span>${severity(f.severity)}</button>`).join('')}${ds.length?'<div class="search-section">AUDIT AREAS</div>':''}${ds.map(d=>`<button class="search-result" data-action="domain" data-id="${d.id}">${icon(d.icon,'aqua')}<span><strong>${d.name}</strong></span>${icon('arrow')}</button>`).join('')}${!fs.length&&!ds.length?'<div class="empty"><h3>No matches yet.</h3><p>Try an audit area, resource name or finding ID.</p></div>':''}`;}
  function addMember(){overlay('A stronger team starts here.',`<form id="member-form"><div class="field-row"><label class="field">Full name<input name="name" placeholder="Jamie Taylor" required maxlength="50" autocomplete="name" autofocus></label><label class="field">Role<input name="role" placeholder="Azure Engineer" required maxlength="60"></label></div><p class="note" style="margin-top:17px">Adds an engineer to this local demo workspace. You can immediately assign findings to them. No invitation is sent.</p><p class="form-error" id="member-error" role="alert"></p></form>`,`${button('close','Cancel','x')}<button class="btn btn-primary" form="member-form" type="submit">${icon('plus')}Add engineer</button>`);document.getElementById('member-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),name=String(f.get('name')).trim().replace(/\s+/g,' '),role=String(f.get('role')).trim();if(!name||!role){document.getElementById('member-error').textContent='Enter a name and role.';return;}data.members.push({id:crypto.randomUUID(),name,role,initials:name.split(' ').map(n=>Array.from(n)[0]).slice(0,2).join('').toUpperCase(),color:['mint','purple','blue','peach'][data.members.length%4]});save();closeOverlay();render();toast(`${name} added to the workspace.`);});}
  function resourceModal(id){const r=VX.resources.find(r=>String(r.id)===id);if(!r)return;const fs=data.findings.filter(f=>f.resource===r.name);overlay(esc(r.name),`<div class="field-row"><div class="field">Resource type<strong>${r.type}</strong></div><div class="field">Region<strong>${r.region}</strong></div><div class="field">Resource group<strong class="mono">${r.group}</strong></div><div class="field">Environment<strong>Production / Demo</strong></div></div><div class="status-box" style="margin-top:24px">${icon('checkCircle')}<div><strong>Included in the sample inventory</strong><p class="note">${fs.length?`${fs.length} finding(s) associated with this resource.`:'No findings are associated with this sample inventory record.'} Last demo audit: ${date(data.lastAudit,true)}.</p></div></div>${fs.map(f=>`<button class="search-result" data-action="finding" data-id="${f.id}"><span><strong>${esc(f.title)}</strong><small>${f.id}</small></span>${severity(f.severity)}</button>`).join('')}`,button('close','Close','check'));}
  function help(){overlay('Clarity for your cloud.',`<div class="status-box">${icon('shield')}<div><strong>Vexorion / Azure audit platform</strong><p class="note">Discover risks, give fixes an owner and celebrate verified progress.</p></div></div><ol class="about-list"><li><strong>Audit:</strong> choose from 18 audit areas and run a simulated audit.</li><li><strong>Assign:</strong> click an engineer chip on a finding to change its owner.</li><li><strong>Resolve:</strong> open a finding, follow the guidance and record your verification.</li><li><strong>Level up:</strong> verified fixes award XP to the assigned engineer.</li><li><strong>Review:</strong> keep immutable audit snapshots and download a readable report.</li></ol><p class="note" style="margin-top:20px">All records stay in this browser. No Azure connection is active. Live auditing requires a backend and authorized Azure access.</p><p class="note" style="margin-top:12px">Catalog references: <a class="aqua" href="https://learn.microsoft.com/en-us/security/benchmark/azure/" target="_blank" rel="noopener noreferrer">Microsoft cloud security benchmark</a> · <a class="aqua" href="https://learn.microsoft.com/en-us/azure/well-architected/" target="_blank" rel="noopener noreferrer">Azure Well-Architected Framework</a>.</p>`,button('close','Got it','check',true));}
  function goFindings(domainId){filters={query:'',severity:'all',domain:domainId||'all',status:'active',assignee:'all',tab:'all',page:1};closeOverlay();navigate('findings');}
  function navigate(p){if(location.hash==='#'+p){page=p;mobile=false;render();}else location.hash=p;}
  document.addEventListener('click',e=>{
    if(e.target.classList.contains('modal-backdrop')){closeOverlay();return;}
    const target=e.target.closest('[data-action]');if(!target||target.disabled)return;
    const {action,id,value,kind}=target.dataset;
    switch(action){
      case 'close':closeOverlay();break;
      case 'mobile':mobile=!mobile;render();break;
      case 'finding':openFinding(id);break;
      case 'assign':openAssignment(id);break;
      case 'choose-assignee':{const f=data.findings.find(f=>f.id===id);if(f){f.assignee=value||null;save();closeOverlay();render();toast(value?`Assigned to ${member(value).name}.`:'Finding is now unassigned.');}break;}
      case 'go-findings':goFindings();break;
      case 'domain':goFindings(id);break;
      case 'filter':navigate('findings');setTimeout(()=>document.getElementById('severity-filter')?.focus(),80);break;
      case 'tab':filters.tab=value;filters.page=1;render();break;
      case 'range':range=Number(value);render();break;
      case 'paginate':if(kind==='findings'){filters.page=Number(value);refreshFindings();}else{inventory.page=Number(value);document.getElementById('resource-results').innerHTML=resourceResults();}break;
      case 'search':globalSearch();break;
      case 'score':overlay('A score you can explain.',`<div style="display:flex;justify-content:center">${ring()}</div><p class="note">Demo posture score = 100 × (${checks} catalog checks − 4.5 × ${active().length} active findings) ÷ ${checks}, rounded to the nearest integer. Verified resolutions improve the score. The trend chart is illustrative history.</p><p class="note" style="margin-top:15px">This custom demo score is independent of engineer XP and is not Microsoft Secure Score.</p>`,button('close','Got it','check',true));break;
      case 'workspace':overlay('Your Azure workspace',`<div class="status-box">${icon('cloud')}<div><strong>${esc(data.settings.organization)} / Production</strong><p class="note">1 demo subscription · ${fmt(VX.resources.length)} sample resources · 3 regions</p></div></div><p class="note" style="margin-top:20px">Azure is the only supported cloud in this frontend. This workspace uses local sample data. To change the organization name or weekly goal, open Settings.</p>`,`<a class="btn btn-primary" href="#settings" data-action="close">${icon('settings')}Open settings</a>`);break;
      case 'notifications':overlay('Your workspace, in motion.',`<div class="activity-list" style="padding:0;flex-direction:column">${data.activity.slice(0,6).map(activityItem).join('')}</div>`,`<a class="btn btn-primary" href="#activity" data-action="close">${icon('activity')}View all activity</a>`);break;
      case 'audit':auditModal();break;
      case 'select-scope':{const els=[...document.querySelectorAll('[name="audit-scope"]')],all=els.every(el=>el.checked);els.forEach(el=>el.checked=!all);scopeCount();break;}
      case 'start-audit':startAudit();break;
      case 'scan-progress':showScan();break;
      case 'report':openReport(id);break;
      case 'export':{const report=VX.snapshot(data);data.auditNumber--;exportHTML({...report,id:'WORKSPACE-SNAPSHOT'});break;}
      case 'download-report':{const r=data.reports.find(r=>r.id===id);if(r)exportHTML(r);break;}
      case 'export-csv':exportCSV(filteredFindings());break;
      case 'export-resources':{const rows=[['Name','Type','Resource group','Region'],...filteredResources().map(r=>[r.name,r.type,r.group,r.region])];download('vexorion-resources.csv','\uFEFF'+rows.map(row=>row.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8');toast('Resource inventory exported.');break;}
      case 'resource':resourceModal(id);break;
      case 'add-member':addMember();break;
      case 'help':help();break;
      case 'reset':overlay('Start fresh?',`<p class="note">This resets all local findings, assignments, XP, reports, engineers and workspace preferences to the original sample data. This action cannot be undone.</p>`,`${button('close','Keep my workspace','x')}${button('confirm-reset','Reset demo','refresh',true)}`);break;
      case 'confirm-reset':if(scan){scan=null;}data=VX.seed();filters={query:'',severity:'all',domain:'all',status:'active',assignee:'all',tab:'all',page:1};save();closeOverlay();render();toast('Demo workspace reset. A fresh start.');break;
    }
  });
  document.addEventListener('keydown',e=>{
    if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();globalSearch();}
    if(e.key==='Escape'){closeOverlay();if(mobile){mobile=false;render();}}
    const dialog=document.querySelector('[role="dialog"]');
    if(e.key==='Tab'&&dialog){const items=[...dialog.querySelectorAll('a[href],button:not(:disabled),input:not(:disabled),select:not(:disabled),[tabindex="0"]')].filter(el=>el.offsetParent!==null),first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){last?.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first?.focus();e.preventDefault();}}
  });
  function route(){const requested=location.hash.slice(1).split('?')[0];page=pageNames[requested]?requested:'overview';mobile=false;closeOverlay();render();window.scrollTo(0,0);}
  window.addEventListener('hashchange',route);
  route();
})();
